UPDATE INT_SERVERFUNCTION SET NAME = COALESCE(NULL, NAME), DESCRIPTION = COALESCE(NULL, DESCRIPTION), TYPE = COALESCE(NULL, TYPE), JDBC_ID = NULL, CODE = COALESCE('SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''DESCRICAO'',t.DESCRICAO,''COR'',t.COR,''ATIVO'',t.ATIVO,''CRIADO_EM'',t.CRIADO_EM,''TIPO_DRIVER'',t.TIPO_DRIVER,''ORIGEM'',t.ORIGEM)) FROM DRIVERS t WHERE t.ID = {{driverId}}),JSON_ARRAY()) AS DRIVER,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',c.ID,''CODIGO'',c.CODIGO,''NOME'',c.NOME)) FROM CONTA_CONTABIL c),JSON_ARRAY()) AS CONTAS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''DRIVER_ID'',t.DRIVER_ID,''CONTA_ID'',t.CONTA_ID,''FORMULA'',t.FORMULA,''DESCRICAO'',t.DESCRICAO,''TIPO'',t.TIPO,''ORDEM'',t.ORDEM,''NOME_CUSTOM'',t.NOME_CUSTOM,''CODIGO'',t.CODIGO,''LABEL'',t.LABEL,''ESCONDER'',t.ESCONDER,''NEGRITO'',t.NEGRITO,''FORMATO'',t.FORMATO)) FROM DRIVER_FORMULA t WHERE t.DRIVER_ID = {{driverId}}),JSON_ARRAY()) AS LINHAS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CONTA_ID'',cd.CONTA_ID)) FROM CONTA_DRIVER cd WHERE cd.DRIVER_ID = {{driverId}}),JSON_ARRAY()) AS VINCULOS,
  COALESCE((SELECT JSON_OBJECT(''ID'',v.ID,''NUMERO'',v.NUMERO,''CRIADO_EM'',v.CRIADO_EM,''SNAPSHOT'',v.SNAPSHOT) FROM DRIVER_VERSAO v WHERE v.DRIVER_ID = {{driverId}} ORDER BY v.NUMERO DESC LIMIT 1),JSON_OBJECT()) AS ULTIMA_VERSAO', CODE), PUBLIC_EXECUTION = COALESCE(NULL, PUBLIC_EXECUTION), CRON_EXPRESSION = NULL, CRON_INPUT_JSON = NULL WHERE NAME = 'hotFormulasModeloBase';
